    "name": "Валентина Ковальчук",
    "rating": 5,
    "text": "За шість місяців я перебрала вже цілу купу різних моделей, але всі вони мали якісь недоліки. Деякі взагалі довелося викинути. А от цей від arhimed за потужністю не поступаються philips. Якщо вагаєтеся, точно раджу спробувати. Я користувалася Medela, Spectra, Momcozy, ручними, силіконовими нічого не зрівняється з цим. Особливо коли в мене почали падати кількість молока, цей пристрій дуже виручив.",
